#include "engine/replay.hpp"
#include "engine/replay_ghost.hpp"
#include "engine/scene_archive.hpp"
#include "../examples/driving_replay.hpp"
#include "../src/vehicle_example.hpp"
#include <iostream>
#include <limits>
using namespace engine;
namespace {
int checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}template<class F>void rejects(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}check(failed,"Expected rejection");}
ReplayData data(){ReplayData d;d.context="test-course-v1";d.poses={"car"};d.values={"speed"};ReplayFrame a;a.poses.push_back({});a.values={0};auto b=a;b.time=1;b.poses[0].translation={10,0,0};b.poses[0].rotation={0,1,0,0};b.values={20};d.frames={a,b};d.events={{0,"start",""},{.4,"marker","wall"},{1,"finish","done"}};return d;}
void core(){auto d=data();auto r=ReplayRecording::create(d);check(r->duration()==1,"Duration");auto mid=r->sample(.5);check(std::abs(mid.poses[0].translation.x-5)<1e-5,"Position blend");check(std::abs(mid.values[0]-10)<1e-5,"Telemetry blend");check(std::abs(std::abs(mid.poses[0].rotation.y)-.7071068f)<1e-4,"Quaternion blend");check(r->eventsBetween(0,.5).size()==1,"Event bounds");check(r->eventsBetween(.4,1).size()==1,"Event boundaries");const auto file=ReplayArchive::save(*r);check(ReplayArchive::save(*ReplayArchive::load(file))==file,"File roundtrip");rejects([&]{ReplayArchive::load(file+"trailing");});rejects([&]{ReplayArchive::load("WEGHOST 9");});rejects([&]{ReplayArchive::load(std::string(65*1024*1024,'x'));});
    for(int kind=0;kind<13;++kind){auto bad=d;if(kind==0)bad.frames[1].time=0;if(kind==1)bad.frames[0].time=.1;if(kind==2)bad.frames[1].time=601;if(kind==3)bad.frames[1].poses.clear();if(kind==4)bad.frames[1].poses[0].scale.x=0;if(kind==5)bad.frames[1].poses[0].rotation={0,0,0,0};if(kind==6)bad.frames[1].values[0]=std::numeric_limits<float>::quiet_NaN();if(kind==7)bad.events[1].time=2;if(kind==8)bad.events[1].name="bad\nname";if(kind==9)bad.poses.push_back("car");if(kind==10)bad.frames[1].poses[0].translation.x=std::numeric_limits<float>::infinity();if(kind==11)bad.events[0].time=.6;if(kind==12)bad.context.clear();rejects([&]{ReplayRecording::create(bad);});}
    d.frames[1].cut=true;check(ReplayRecording::create(d)->sample(.99).poses[0].translation.x==0,"Cut must not interpolate teleport");check(ReplayRecording::create(d)->sample(1).poses[0].translation.x==10,"Cut boundary");
    auto schema=data();schema.frames.clear();schema.events.clear();ReplayRecorder recorder(schema);check(recorder.capture(data().frames[0]),"Initial capture");rejects([&]{recorder.capture(data().frames[0]);});check(recorder.data().frames.size()==1,"Failed capture mutated buffer");rejects([&]{recorder.event({1,"future",""});});check(recorder.capture(data().frames[1]),"Second capture");check(recorder.event({1,"marker","quote \\\""}),"Event capture");check(recorder.finish()->data().events.size()==1,"Finish");
    ReplayPlayer player(r);player.play();player.advance(.25);check(player.time()==.25,"Clock advance");player.seek(.5);check(!player.playing(),"Seek pauses");player.advance(.1);check(player.time()==.5,"Paused clock");player.setSpeed(2);player.play();player.advance(.25);check(player.time()==1&&!player.playing(),"End pauses");player.play();check(player.time()==0,"Play at end restarts");player.looping=true;player.seek(.9);player.play();player.advance(.1);check(std::abs(player.time()-.1)<1e-8,"Loop wraps");rejects([&]{player.advance(.3);});rejects([&]{player.seek(-1);});rejects([&]{player.setSpeed(0);});
    for(float yaw:{-pi,-2.f,-pi/2,0.f,pi/2,2.f,pi})for(float roll:{-.8f,0.f,.8f}){Transform t{{1,2,3},{.2f,yaw,roll},{1,2,3}};auto p=replayPose(t.matrix());const auto m=replayTransform(p).matrix();for(int i=0;i<16;++i)check(std::abs(m.m[i]-t.matrix().m[i])<.002f,"Pose conversion");}
    auto bad=Mat4::identity();bad.m[4]=.5;rejects([&]{replayPose(bad);});bad=Mat4::identity();bad.m[0]=-1;rejects([&]{replayPose(bad);});
    auto bounded=data();bounded.frames.clear();bounded.events.clear();bounded.poses.clear();for(int i=0;i<32;++i)bounded.poses.push_back("pose"+std::to_string(i));ReplayRecorder limit(bounded);ReplayFrame f;f.poses.resize(32);f.values={0};for(int i=0;i<5625;++i){f.time=i*.01;check(limit.capture(f),"Pose budget admitted too few frames");}f.time=56.25;check(!limit.capture(f)&&limit.data().frames.size()==5625,"Pose budget did not retain valid state");for(int i=0;i<2048;++i)check(limit.event({0,"event",""}),"Event budget admitted too few");check(!limit.event({0,"event",""})&&limit.data().events.size()==2048,"Event budget did not retain valid state");check(ReplayArchive::load(ReplayArchive::save(*limit.finish()))->data().frames.size()==5625,"Budget-edge file roundtrip");
}
void ghost(){Scene scene("Ghost test");auto& actor=scene.spawn("Author");actor.addComponent<MeshComponent>("Source",Mesh::cube());auto& camera=scene.spawn("Camera").addComponent<CameraComponent>();const std::array views{RenderView{&camera}};const auto before=SceneArchive::save(scene,views);const ReplayVisual visual{"Body",Mesh::cube()};ReplayGhost ghost(scene,std::span(&visual,1));std::array<JointPose,2> poses;poses[0].translation={4,2,1};check(ghost.apply(scene,poses),"Apply ghost");ghost.show(scene,true);check(scene.findActor(ghost.actor())->transform.position.x==4,"Ghost pose");check(!scene.findActor(ghost.actor())->getComponent<RigidBodyComponent>(),"Ghost allocated physics");check(SceneArchive::save(scene,views)==before,"Ghost leaked into scene archive");auto invalid=poses;invalid[1].scale.x=0;rejects([&]{ghost.apply(scene,invalid);});check(scene.findActor(ghost.actor())->transform.position.x==4,"Invalid ghost partially applied");Scene foreign;check(!ghost.apply(foreign,poses),"Foreign scene binding");ghost.remove(scene);check(!ghost.apply(scene,poses),"Removed ghost binding stayed live");scene.flushPendingDestroy();check(SceneArchive::save(scene,views)==before,"Removal mutated authoring state");}
void driving(){Scene scene;auto& actor=static_cast<Actor&>(scene.adoptChild(makeVehicleExample()));auto* vehicle=actor.getComponent<VehicleComponent>();auto& ground=scene.spawn("Ground");RigidBodySettings body;body.motion=BodyMotion::Static;ground.addComponent<RigidBodyComponent>("Body",body);ground.addComponent<ColliderComponent>("Collider",CollisionShape::box({30,.25f,80}));ground.transform.position={0,-.25f,0};auto& camera=scene.spawn("Camera").addComponent<CameraComponent>();scene.synchronize();vehicle_example::DrivingReplaySession session(scene,vehicle->id(),"vehicle-course-v1");session.begin(scene);vehicle->submit({1,0,0,0});for(int i=0;i<90;++i){scene.fixedUpdate(1./60);session.update(scene,1./60,1./60);}session.marker("Contact to inspect");check(session.finish(scene),"Driving finish");auto clip=session.clip();check(clip->data().poses.size()==6&&clip->data().frames.size()>35,"Driving samples/wheels");const auto position=actor.transform;session.review(scene,camera);session.seek(scene,.5);session.update(scene,0,.1);check(actor.transform.position.z==position.position.z,"Review moved live physics");check(session.player()->time()==.5,"Seek remained paused");session.player()->play();session.update(scene,0,.1);check(session.player()->time()>.5,"Review presentation clock");session.closeReview(scene);check(camera.follow().enabled==false,"Camera policy not restored");for(const auto& n:actor.children())if(auto* mesh=dynamic_cast<MeshComponent*>(n.get()))check(mesh->visibilityMask==1,"Live visibility not restored");session.player()->setSpeed(2);const auto start=session.race(scene);check(session.player()->speed()==1,"Race retained review speed");check(session.visible()&&session.player()->playing(),"Race ghost");check(std::abs(start.position.z-clip->sample(0).poses[0].translation.z)<1e-6,"Race initial pose");auto wrong=clip->data();wrong.context="another course";rejects([&]{session.adopt(scene,ReplayRecording::create(wrong));});check(session.clip()==clip,"Invalid import replaced good clip");session.clear(scene);scene.flushPendingDestroy();}
}
int main(){try{core();ghost();driving();std::cout<<checks<<" replay checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
